def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))

    # Find the colored boundary bars in the top and bottom rows.
    def runs(row):
        out = []
        i = 0
        while i < w:
            j = i + 1
            while j < w and row[j] == row[i]:
                j += 1
            if row[i] != bg:
                out.append((i, j, row[i]))
            i = j
        return out

    top = max(runs(g[0]), key=lambda x: x[1] - x[0])
    bottom = max(runs(g[-1]), key=lambda x: x[1] - x[0])
    shift = bottom[0] - top[0]
    bar_color = top[2]

    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and g[r][c] != bar_color]

    for r, c, color in markers:
        # Extend each marker upward to the top boundary.
        for rr in range(r):
            if not (rr == 0 and g[rr][c] == bar_color):
                g[rr][c] = color
        g[r][c] = 4

        # Project the marker's column across to the opposite boundary.
        cc = c + shift
        if 0 <= cc < w:
            for rr in range(h):
                if not ((rr == 0 or rr == h - 1) and g[rr][cc] == bar_color):
                    g[rr][cc] = color

    return g
